// Shipped guard for the command-line feature surface: this backend must classify every option the
// pinned upstream generation CLI (src/program/generate.cpp) accepts, and must not silently ignore a
// flag of its own. The table below is generated by work/extract_cli_tables.py from both parsers and
// cross-checked against the newest work/validation/cli-surface-audit-v*.json; the local suite regenerates it and
// compares bytes, so an upstream option that is added, renamed or changes arity makes the suite fail
// instead of disappearing from the port's feature list. What is asserted here is the internal contract:
// unique sorted names, a bucket from the declared set for every row, "ported" only for an option this
// backend really parses, request-path rows carrying a real probe token, and the port's own parser still
// rejecting anything it does not recognise. Host only: no device, and no claim that a classified option
// behaves identically - only that it is accounted for by name.
#include "strata_cli_surface.inc"
#include <algorithm>
#include <cstring>
#include <iostream>
#include <set>
#include <stdexcept>
#include <string>
#include <tuple>
#include <vector>
namespace {
void require(bool ok,const std::string& why){if(!ok) throw std::runtime_error(why);}
const std::vector<std::string>& buckets() {
    static const std::vector<std::string> known{"ported","rule:multi-device-and-peer",
        "rule:cuda-or-sycl-kernel-selection","rule:dump-and-diagnostic-plumbing",
        "rule:allocator-and-transfer-tuning","rule:profiling-and-adaptive-control","rule:multi-modal-input",
        "rule:host-side-reference-knobs","rule:not-a-native-cli-knob","unported:explicit"};
    return known;
}
std::set<std::string> port_options() {
    std::set<std::string> out;
    for(const auto* name:strata_cli_port_options) out.insert(name);
    return out;
}
}
int main(){try {
    require(strata_cli_port_rejects_unknown_options,"the native tool no longer rejects unknown options, "
        "so a mistyped or unimplemented flag would be ignored silently");
    const auto port=port_options();
    require(port.size()==strata_cli_port_option_count,"duplicate option names in this backend's parser");
    std::size_t ported=0,request_path=0,unported=0;
    std::string previous;
    std::set<std::string> names;
    for(const auto& row:strata_cli_surface) {
        const auto& name=std::get<0>(row);
        const std::string text(name);
        require(text==previous || text>previous,"the generated table is not sorted, so regeneration "
            "could not be compared byte for byte");
        previous=text;
        require(names.insert(text).second,"duplicate upstream option "+text);
        const std::string bucket(std::get<2>(row));
        require(std::find(buckets().begin(),buckets().end(),bucket)!=buckets().end(),
            "option "+text+" carries a bucket outside the declared set");
        if(bucket=="ported") {
            require(port.count(text),"option "+text+" is claimed as ported but this backend's parser does not "
                "match on it");
            ++ported;
        } else if(bucket=="rule:not-a-native-cli-knob") {
            require(std::strlen(std::get<3>(row)),"option "+text+" is claimed to live on the request path with "
                "no probe token to verify");
            require(!port.count(text),"option "+text+" is parsed by name yet bucketed as request-path only");
            ++request_path;
        } else {
            require(!port.count(text),"option "+text+" is bucketed as absent but this backend does parse it");
            if(bucket=="unported:explicit") ++unported;
        }
    }
    require(names.size()==strata_cli_upstream_count,"the table does not hold every upstream option");
    std::size_t extra=0;
    for(const auto& name:port) if(!names.count(name)) ++extra;
    require(ported+extra==port.size(),"this backend's option count is not the sum of ported upstream options "
        "and its own extensions");
    require(ported>0 && request_path>0 && extra>0,"a required classification bucket came up empty, "
        "which means the generated table no longer describes a real feature surface");
    // The exact counts are pinned by the suite step that regenerates the table and compares bytes, so
    // they are not repeated here: a duplicate guard would only add a second place to update.
    std::cout<<"PASS cli surface guard: "<<names.size()<<" upstream options classified ("<<ported<<
        " ported by name, "<<request_path<<" verified request-path capabilities, "<<unported<<
        " explicitly unported features, "<<extra<<" this-backend-only options), sorted and unique, every "
        "bucket declared, unknown options still rejected, and the suite's byte-comparison of the generated "
        "table guards the source against silent drift; no device\n";
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
